const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const timestamp = headers['x-reverb-timestamp'];
const received_signature = headers['x-reverb-signature'];
if (typeof timestamp !== 'string' || typeof received_signature !== 'string') throw new Error('Signed reporting request required');
const timestampMs = /^\d+$/.test(timestamp) ? Number(timestamp) * 1000 : Number.NaN;
if (!Number.isFinite(timestampMs) || Math.abs(Date.now() - timestampMs) > 300000) throw new Error('Request timestamp is stale');
return [{ json: { body, timestamp, received_signature, body_json: JSON.stringify(body) } }];

const received = String($json.received_signature).replace(/^sha256=/, '');
if (!/^[a-f0-9]{64}$/i.test(received) || received.toLowerCase() !== String($json.expected_signature).toLowerCase()) throw new Error('Invalid internal request signature');
const input = $json.body;
if (typeof input.campaignId !== 'string' || input.campaignId.trim() === '') throw new Error('campaignId is required');
const trigger = input.trigger ?? (input.activationUrl ? 'CAMPAIGN_ACTIVATION' : null);
if (!['CAMPAIGN_ACTIVATION','RESERVATION_UPDATE','CAMPAIGN_COMPLETION'].includes(trigger)) throw new Error('Unsupported reporting trigger');
return [{ json: { campaignId: input.campaignId, trigger } }];

const campaignId = $json.campaignId;
const requests = [
  ['get_campaign', { id: campaignId }],
  ['get_campaign_options', { campaignId }],
  ['get_campaign_asset', { campaignId }],
  ['get_transaction', { campaignId }],
  ['list_reservations', { campaignId }],
  ['list_audit_events', { campaignId }],
  ['list_providers', {}],
  ['list_packages', {}]
];
const timestamp = Math.floor(Date.now() / 1000).toString();
return requests.map(([operation, data]) => { const storage_body = { operation, request_id: 'report:' + operation + ':' + campaignId, data }; return { json: { storage_body, storage_json: JSON.stringify(storage_body), timestamp } }; });

const records = {};
for (const item of $input.all()) { const response = item.json; if (typeof response.operation === 'string') records[response.operation] = response.data; }
const campaign = records.get_campaign;
const transaction = records.get_transaction;
if (!campaign || !transaction) throw new Error('Campaign and transaction are required for reporting');
for (const listName of ['get_campaign_options','list_reservations','list_audit_events','list_providers','list_packages']) if (!Array.isArray(records[listName])) records[listName] = [];
return [{ json: { campaign, options: records.get_campaign_options, asset: records.get_campaign_asset, transaction, reservations: records.list_reservations, auditEvents: records.list_audit_events, providers: records.list_providers, packages: records.list_packages } }];

const orderId = $json.transaction.merchantOrderId;
if (typeof orderId !== 'string' || orderId.trim() === '') throw new Error('Merchant order is required for reporting');
const storage_body = { operation: 'get_merchant_order', request_id: 'report:order:' + orderId, data: { id: orderId } };
return [{ json: { storage_body, storage_json: JSON.stringify(storage_body), timestamp: Math.floor(Date.now() / 1000).toString() } }];

const loaded = $('Aggregate Report Lookups').item.json;
const campaign = loaded.campaign;
const transaction = loaded.transaction;
const order = $('Load Merchant Order').item.json.data;
const spot = $json;
if (!order || !spot || typeof spot.name !== 'string') throw new Error('Merchant order and Spot are required for reporting');
const provider = loaded.providers.find((item) => item.id === transaction.providerId);
const promotionPackage = loaded.packages.find((item) => item.id === transaction.packageId);
if (!provider || !promotionPackage) throw new Error('Selected provider and package are required for reporting');
const selectedOption = loaded.options.find((item) => item.packageId === transaction.packageId) ?? null;
const confirmed = loaded.reservations.filter((item) => !item.isTest && ['BOOKED','COMPLETED'].includes(item.status));
const confirmedReservationCount = confirmed.length;
const confirmedGuestCount = confirmed.reduce((sum, item) => sum + Number(item.seatCount || 0), 0);
const unusedCapacity = Number(campaign.unusedCapacity);
const spendPaise = Number(order.amountPaise ?? transaction.amountPaise ?? 0);
const budgetPaise = Number(campaign.maxBudgetPaise);
const capacityRecoveryPercent = unusedCapacity > 0 ? Math.min(100, Math.round((confirmedGuestCount / unusedCapacity) * 10000) / 100) : 0;
const actualCostPerReservationPaise = confirmedReservationCount > 0 ? Math.ceil(spendPaise / confirmedReservationCount) : null;
const estimatedRevenueRecoveredPaise = confirmedGuestCount * Number(spot.averageBookingValuePaise || 0);
const remainingBudgetPaise = Math.max(0, budgetPaise - spendPaise);
for (const value of [spendPaise,budgetPaise,estimatedRevenueRecoveredPaise,remainingBudgetPaise]) if (!Number.isSafeInteger(value) || value < 0) throw new Error('Reporting money must be non-negative integer paise');
const safeReservations = loaded.reservations.map((item) => ({ reservationAt: item.reservationAt, seatCount: Number(item.seatCount), status: item.status, isDemoBooking: item.isTest === true, testLabel: item.isTest ? item.testLabel : null }));
const safeAuditTrail = loaded.auditEvents.map((item) => ({ eventType: item.eventType, occurredAt: item.occurredAt, previousState: item.previousState ?? null, nextState: item.nextState ?? null }));
let creative = {};
try { creative = JSON.parse(loaded.asset?.content ?? '{}'); } catch { creative = { caption: String(loaded.asset?.content ?? '') }; }
const stripPrivate = (value) => { if (Array.isArray(value)) return value.map(stripPrivate); if (!value || typeof value !== 'object') return value; const output = {}; for (const [key, child] of Object.entries(value)) { if (/(customer|contact|phone|email|tracking|activationId|token|secret|authori[sz]ation|credential|card|cvv|pan|password)/i.test(key)) continue; output[key] = stripPrivate(child); } return output; };
const approvedCreative = stripPrivate(creative);
const metrics = { initialUnusedCapacity: unusedCapacity, targetReservations: Number(campaign.targetReservations), confirmedReservationCount, confirmedGuestCount, capacityRecoveryPercent, remainingCapacity: Math.max(0, unusedCapacity - confirmedGuestCount), promotionSpendPaise: spendPaise, actualCostPerReservationPaise, estimatedRevenueRecoveredPaise, remainingBudgetPaise };
const report = { campaignId: campaign.id, trigger: $('Verify And Validate Report Trigger').item.json.trigger, generatedAt: new Date().toISOString(), campaignStatus: campaign.status, spot: { id: spot.id, name: spot.name, category: spot.category, timezone: spot.timezone }, selectedProvider: { id: provider.id, name: provider.name }, selectedPackage: { id: promotionPackage.id, title: promotionPackage.title }, metrics, reservations: safeReservations, auditTrail: safeAuditTrail, transactionSummary: { transactionId: transaction.id, merchantOrderId: order.id, status: transaction.status, orderStatus: order.status, currency: transaction.currency, amountPaise: spendPaise }, approvedCreative };
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[char]);
const providerComparisonHtml = '<!doctype html><html><body><h1>Provider comparison</h1><p>Campaign: ' + esc(campaign.id) + '</p><table><thead><tr><th>Package</th><th>Score</th><th>Price (paise)</th><th>Eligible</th></tr></thead><tbody>' + loaded.options.map((option) => '<tr><td>' + esc(option.packageId) + '</td><td>' + esc(option.score) + '</td><td>' + esc(option.totalCostPaise) + '</td><td>' + esc(option.passesDeterministicChecks) + '</td></tr>').join('') + '</tbody></table></body></html>';
const ownerEmail = String($env.DEMO_OWNER_EMAIL || '');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(ownerEmail)) throw new Error('Spot owner email is not configured');
const emailHtml = '<!doctype html><html><body><h1>Reverb Fill campaign report</h1><p><strong>' + esc(spot.name) + '</strong></p><p>Status: ' + esc(campaign.status) + '</p><ul><li>Reservations: ' + confirmedReservationCount + '</li><li>Guests recovered: ' + confirmedGuestCount + '</li><li>Capacity recovery: ' + capacityRecoveryPercent + '%</li><li>Spend: ' + spendPaise + ' paise</li><li>Actual CPA: ' + (actualCostPerReservationPaise ?? 'Not available') + ' paise</li><li>Estimated revenue recovered: ' + estimatedRevenueRecoveredPaise + ' paise</li><li>Remaining budget: ' + remainingBudgetPaise + ' paise</li></ul><p>Test bookings are labelled and excluded from these performance totals.</p></body></html>';
return [{ json: { campaign, spot, provider, promotionPackage, selectedOption, asset: loaded.asset, report, providerComparisonHtml, campaignBrief: String(approvedCreative.providerBrief ?? ''), ownerEmail, emailHtml } }];

const source = $('Build Sanitized Campaign Report').item.json;
const report = source.report;
return [{ json: { id: 'report_' + report.campaignId, campaignId: report.campaignId, optionId: source.selectedOption?.id ?? 'reporting_snapshot', type: 'OWNER_SUMMARY', content: JSON.stringify(report), generatedBy: 'SYSTEM', model: '', requiresOwnerApproval: false, createdAt: report.generatedAt } }];

const source = $('Build Sanitized Campaign Report').item.json;
const report = source.report;
const artifacts = [
  ['approved-creative.json', 'application/json', JSON.stringify(report.approvedCreative, null, 2)],
  ['campaign-brief.txt', 'text/plain', source.campaignBrief],
  ['provider-comparison.html', 'text/html', source.providerComparisonHtml],
  ['transaction-summary.json', 'application/json', JSON.stringify(report.transactionSummary, null, 2)],
  ['campaign-report.json', 'application/json', JSON.stringify(report, null, 2)]
];
return artifacts.map(([fileName, mimeType, content]) => ({ json: { fileName, mimeType, content } }));
